"use client"

import * as React from "react"
import Link from "next/link"
import { ExternalLinkIcon, PlusIcon, XIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { displayValue, gateOpen, keyDef, normaliseKey, optionParts, splitMulti, type CanonicalKey } from "@/lib/forms/keys"
import { askedSections, formById, type FormId } from "@/lib/forms/programs"
import { markDone, mergeProfile, rowCount, sectionKnown, valueFor, valuesFor, type Values } from "@/lib/forms/profile"
import { keyOnRow, plainKeys, rowKeys, type AskInput, type AskResult, type ChatField } from "@/lib/chat/form-tools"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Field, FieldDescription, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { InputGroup, InputGroupAddon, InputGroupInput, InputGroupText } from "@/components/ui/input-group"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"

// One section of a form, as controls in the chat.
//
// Ported from livingston's ChatFormFields: values are held the way they are
// stored (ten digits, plain money, ISO dates) and shown the way they are
// typed, so the profile never carries a formatted string the fill would have
// to unpick. What is new is the profile: a key the applicant has already
// answered arrives prefilled and folded into a one-line summary above the
// open fields, with Edit, so a returning applicant types only what is not
// known yet. Submitting writes the values into the profile and hands the
// model a receipt — which keys were answered — never the values.

const digits = (s: string) => s.replace(/\D/g, "")

function formatTel(stored: string) {
  const d = digits(stored).slice(0, 10)
  if (d.length <= 3) return d.length ? `(${d}` : ""
  if (d.length <= 6) return `(${d.slice(0, 3)}) ${d.slice(3)}`
  return `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`
}

function formatSsn(stored: string) {
  const d = digits(stored).slice(0, 9)
  if (d.length <= 3) return d
  if (d.length <= 5) return `${d.slice(0, 3)}-${d.slice(3)}`
  return `${d.slice(0, 3)}-${d.slice(3, 5)}-${d.slice(5)}`
}

function formatMoney(stored: string) {
  const m = /^(\d*)(\.\d{0,2})?/.exec(stored.replace(/[^\d.]/g, "")) ?? []
  const whole = m[1] ?? ""
  const frac = m[2] ?? ""
  return (whole ? Number(whole).toLocaleString("en-US") : "") + frac
}
const storeMoney = (typed: string) => {
  const clean = typed.replace(/[^\d.]/g, "")
  const [whole = "", ...rest] = clean.split(".")
  const frac = rest.length ? `.${rest.join("").slice(0, 2)}` : ""
  return whole.replace(/^0+(?=\d)/, "") + frac
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

/** What is wrong with a value, or nothing. */
function problem(f: ChatField, v: string): string | null {
  const t = v.trim()
  if (!t) return f.required ? "Needed to go on." : null
  if (f.kind === "ssn" && digits(t).length !== 9) return "Nine digits."
  if (f.kind === "tel" && digits(t).length !== 10) return "Ten digits."
  if (f.kind === "email" && !EMAIL.test(t)) return "Not an email address."
  if (f.kind === "date" && !/^\d{4}-\d{2}-\d{2}$/.test(t)) return "A full date."
  return null
}

type Control = { field: ChatField; id: string; value: string; set: (v: string) => void; error?: string }

export function Control({ field: f, id, value: v, set, error }: Control) {
  const opts = (f.options ?? []).map(optionParts)
  const invalid = error ? true : undefined
  if (f.kind === "textarea") return <Textarea id={id} rows={2} value={v} placeholder={f.placeholder} aria-invalid={invalid} onChange={(e) => set(e.target.value)} />
  if (f.kind === "select")
    return (
      <Select value={v || null} onValueChange={(next) => set(String(next ?? ""))} items={opts}>
        <SelectTrigger id={id} aria-label={f.label} aria-invalid={invalid} className="w-full">
          <SelectValue placeholder="Choose…" />
        </SelectTrigger>
        <SelectContent align="start" className="w-max min-w-44">
          {opts.map((o) => (
            <SelectItem key={o.value} value={o.value} className="whitespace-nowrap">
              {o.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    )
  if (f.kind === "radio")
    return (
      <RadioGroup value={v} onValueChange={(next) => set(String(next ?? ""))} className="gap-1.5" aria-invalid={invalid}>
        {opts.map((o) => (
          <Label key={o.value} className="flex items-center gap-2 font-normal">
            <RadioGroupItem value={o.value} id={`${id}-${o.value}`} />
            {o.label}
          </Label>
        ))}
      </RadioGroup>
    )
  if (f.kind === "yesno" || f.kind === "attest")
    return (
      <div className="flex flex-wrap gap-1.5" role="radiogroup" aria-label={f.label} aria-invalid={invalid}>
        {(opts.length ? opts : [{ value: "yes", label: "Yes" }, { value: "no", label: "No" }]).map((o) => (
          <Button key={o.value} type="button" size="sm" variant={v === o.value ? "default" : "outline"} role="radio" aria-checked={v === o.value} onClick={() => set(v === o.value ? "" : o.value)}>
            {o.label}
          </Button>
        ))}
      </div>
    )
  if (f.kind === "checkbox") {
    const chosen = splitMulti(v)
    return (
      <div className="flex flex-col gap-1.5" role="group" aria-label={f.label} aria-invalid={invalid}>
        {opts.map((o) => {
          const on = chosen.includes(o.value)
          return (
            <Label key={o.value} className="flex items-center gap-2 font-normal">
              <Checkbox
                id={`${id}-${o.value}`}
                checked={on}
                onCheckedChange={(next) => {
                  const rest = chosen.filter((c) => c !== o.value)
                  set((next ? [...rest, o.value] : rest).join(", "))
                }}
              />
              {o.label}
            </Label>
          )
        })}
      </div>
    )
  }
  if (f.kind === "date") return <Input id={id} type="date" value={v} aria-invalid={invalid} onChange={(e) => set(e.target.value)} />
  if (f.kind === "money")
    return (
      <InputGroup>
        <InputGroupAddon>
          <InputGroupText>$</InputGroupText>
        </InputGroupAddon>
        <InputGroupInput id={id} inputMode="decimal" value={formatMoney(v)} placeholder={f.placeholder ?? "0"} aria-invalid={invalid} onChange={(e) => set(storeMoney(e.target.value))} />
      </InputGroup>
    )
  if (f.kind === "tel") return <Input id={id} type="tel" inputMode="numeric" autoComplete="tel" value={formatTel(v)} placeholder={f.placeholder ?? "(555) 555-5555"} aria-invalid={invalid} onChange={(e) => set(digits(e.target.value).slice(0, 10))} />
  if (f.kind === "ssn") return <Input id={id} inputMode="numeric" autoComplete="off" value={formatSsn(v)} placeholder="123-45-6789" aria-invalid={invalid} onChange={(e) => set(digits(e.target.value).slice(0, 9))} />
  if (f.kind === "email") return <Input id={id} type="email" inputMode="email" autoComplete="email" value={v} placeholder={f.placeholder ?? "you@example.com"} aria-invalid={invalid} onChange={(e) => set(e.target.value)} />
  if (f.kind === "number") return <Input id={id} inputMode="numeric" value={v} placeholder={f.placeholder} aria-invalid={invalid} onChange={(e) => set(e.target.value.replace(/[^\d.]/g, ""))} />
  return <Input id={id} type="text" value={v} placeholder={f.placeholder} aria-invalid={invalid} onChange={(e) => set(e.target.value)} />
}

const TONE: Record<"caution" | "info", string> = {
  caution: "border-amber-400/60 bg-amber-50 dark:border-amber-500/40 dark:bg-amber-950/30",
  info: "border-blue-500/50 bg-blue-50 dark:border-blue-500/40 dark:bg-blue-950/30",
}

export function AskWidget({
  input,
  form,
  answered,
  compact,
  onSubmit,
}: {
  input: AskInput
  form: FormId | null
  /** The receipt already returned, when this widget is being re-rendered from a saved run. */
  answered?: AskResult
  compact?: boolean
  onSubmit: (result: AskResult) => void
}) {
  const plain = React.useMemo(() => plainKeys(input.fields), [input.fields])
  const rows = React.useMemo(() => rowKeys(input.fields), [input.fields])
  const known = React.useCallback((key: string) => (form ? (valueFor(form, key) ?? "") : ""), [form])

  // Rows the profile already holds, at least the minimum.
  const [rowN, setRowN] = React.useState(() => {
    const have = form && input.repeat ? rowCount(valuesFor(form), input.repeat.key) : 0
    return Math.max(input.repeat?.min ?? 1, have, 1)
  })
  const allFields = React.useMemo(() => {
    const out: ChatField[] = [...plain]
    if (rows.length) for (let n = 1; n <= rowN; n += 1) for (const f of rows) out.push({ ...f, key: keyOnRow(f.key, n) })
    return out
  }, [plain, rows, rowN])

  const fromProfile = React.useCallback(() => Object.fromEntries(allFields.map((f) => [f.key, known(f.key)])), [allFields, known])
  const [values, setValues] = React.useState<Values>(fromProfile)
  React.useEffect(() => setValues((prev) => ({ ...fromProfile(), ...prev })), [fromProfile])
  const [errors, setErrors] = React.useState<Record<string, string>>({})
  const [done, setDone] = React.useState<AskResult | undefined>(answered)
  const [editing, setEditing] = React.useState(false)
  // Known keys start folded; Edit opens them.
  const [showKnown, setShowKnown] = React.useState(false)

  const set = (key: string, v: string) => {
    setValues((p) => ({ ...p, [key]: v }))
    if (errors[key]) setErrors((p) => ({ ...p, [key]: "" }))
  }

  const isKnown = (f: ChatField) => !keyDef(f.key)?.always && Boolean(known(f.key))
  // A gated field shows while its parent answer calls for it: the "other"
  // detail beside an "other", the address that differs beside "different".
  const applies = (f: ChatField) => gateOpen(f.key, { ...(form ? valuesFor(form) : {}), ...values })
  const knownFields = allFields.filter((f) => isKnown(f) && applies(f))
  const openFields = (showKnown || editing ? allFields : allFields.filter((f) => !isKnown(f))).filter(applies)

  const submit = () => {
    const problems: Record<string, string> = {}
    for (const f of allFields.filter(applies)) {
      const p = problem(f, values[f.key] ?? "")
      if (p) problems[f.key] = p
    }
    setErrors(problems)
    if (Object.keys(problems).length) return
    const merged: Values = {}
    for (const f of allFields) merged[f.key] = applies(f) ? (values[f.key] ?? "").trim() : ""
    mergeProfile(merged)
    if (form) markDone(form, input.section)
    const answeredKeys: CanonicalKey[] = []
    const skipped: CanonicalKey[] = []
    for (const f of allFields.filter(applies)) (merged[f.key] ? answeredKeys : skipped).push(f.key)
    // The next section still open, from the profile as it now stands — so
    // the model can go on without holding the schema or a tally.
    let next: Extract<AskResult, { section: string }>["next"] = null
    const program = form ? formById(form) : undefined
    if (program) {
      const now = valuesFor(form!)
      const order = askedSections(program)
      const at = order.findIndex((s) => s.n === input.section)
      for (const s of order.slice(at + 1)) {
        const open = sectionKnown(s, now).open
        if (open.length) {
          next = { section: s.n, title: s.title, open }
          break
        }
      }
    }
    const result: AskResult = { section: input.section, answered: answeredKeys, skipped, next }
    setDone(result)
    setEditing(false)
    if (!done) onSubmit(result)
  }

  const grid = compact ? "grid grid-cols-1 gap-3" : "grid grid-cols-1 gap-3 sm:grid-cols-2"
  const wide = (f: ChatField) => f.kind === "textarea" || f.kind === "checkbox" || f.tone || (f.options?.length ?? 0) > 3

  const control = (f: ChatField) => {
    const id = `${input.section}-${f.key}`.replace(/[^\w-]/g, "_")
    const error = errors[f.key]
    if (f.tone) {
      const boxed = (
        <div key={f.key} className={cn("relative rounded-lg border p-3", TONE[f.tone], !compact && "sm:col-span-2")}>
          {f.href && (
            <a href={f.href} target="_blank" rel="noopener noreferrer" aria-label="Read the page this refers to" className="absolute top-2 right-2 flex size-7 items-center justify-center rounded-md text-foreground/60 hover:bg-background/60 hover:text-foreground">
              <ExternalLinkIcon className="size-4" />
            </a>
          )}
          {f.hint && <p className="mb-2.5 pr-8 text-sm leading-relaxed">{f.hint}</p>}
          <Label htmlFor={id} className="mb-1.5">
            {f.label}
          </Label>
          <Control field={f} id={id} value={values[f.key] ?? ""} set={(v) => set(f.key, v)} error={error} />
          {error && <FieldError className="mt-1.5">{error}</FieldError>}
        </div>
      )
      return boxed
    }
    return (
      <Field key={f.key} data-invalid={error ? true : undefined} className={cn(wide(f) && !compact && "sm:col-span-2")}>
        <FieldLabel htmlFor={id}>
          {f.label}
          {f.required && <span className="text-muted-foreground">·</span>}
        </FieldLabel>
        <Control field={f} id={id} value={values[f.key] ?? ""} set={(v) => set(f.key, v)} error={error} />
        {f.hint && !error && <FieldDescription>{f.hint}</FieldDescription>}
        {error && <FieldError>{error}</FieldError>}
      </Field>
    )
  }

  // The rows of a repeating section, each its own small block.
  const rowBlocks = () => {
    if (!rows.length) return null
    const blocks: React.ReactNode[] = []
    for (let n = 1; n <= rowN; n += 1) {
      const these = openFields.filter((f) => rows.some((r) => keyOnRow(r.key, n) === f.key))
      if (!these.length) continue
      blocks.push(
        <div key={n} className={cn("rounded-lg border p-3", !compact && "sm:col-span-2")}>
          <div className="mb-2 flex items-center justify-between">
            <span className="text-sm font-medium">
              {input.repeat?.label ?? "Row"} {n}
            </span>
            {n === rowN && n > (input.repeat?.min ?? 1) && (
              <Button type="button" variant="ghost" size="icon-xs" aria-label="Remove this row" onClick={() => setRowN((k) => k - 1)}>
                <XIcon />
              </Button>
            )}
          </div>
          <div className={grid}>{these.map(control)}</div>
        </div>
      )
    }
    return blocks
  }

  // Submitted: a read-only summary, with Edit.
  if (done && !editing) {
    const lines = allFields.filter((f) => applies(f) && (values[f.key] ?? "").trim())
    return (
      <div data-slot="ask-widget" className="rounded-lg border bg-muted/30 p-3 text-sm">
        <div className="mb-1 flex items-center justify-between gap-2">
          <span className="font-medium">{input.title}</span>
          <Button type="button" variant="ghost" size="xs" className="text-muted-foreground" onClick={() => setEditing(true)}>
            Edit
          </Button>
        </div>
        {lines.length ? (
          <dl className={cn("grid gap-x-4 gap-y-0.5", compact ? "grid-cols-1" : "sm:grid-cols-2")}>
            {lines.map((f) => (
              <div key={f.key} className="flex min-w-0 justify-between gap-3 text-muted-foreground">
                <dt className="truncate">{f.label}</dt>
                <dd className="truncate text-right text-foreground">{displayValue(normaliseKey(f.key), values[f.key])}</dd>
              </div>
            ))}
          </dl>
        ) : (
          <p className="text-muted-foreground">Nothing answered.</p>
        )}
      </div>
    )
  }

  return (
    <form
      data-slot="ask-widget"
      className="rounded-lg border bg-muted/30 p-3"
      onSubmit={(e) => {
        e.preventDefault()
        submit()
      }}
    >
      <div className="mb-3 flex flex-col gap-1">
        <span className="text-sm font-medium">{input.title}</span>
        {input.intro && <p className="text-sm text-muted-foreground">{input.intro}</p>}
      </div>

      {knownFields.length > 0 && !showKnown && !editing && (
        <div className="mb-3 flex items-start justify-between gap-3 rounded-md border border-dashed px-3 py-2 text-sm">
          <p className="min-w-0 text-muted-foreground">
            Already known:{" "}
            {knownFields.map((f, i) => (
              <React.Fragment key={f.key}>
                {i > 0 && ", "}
                <span className="text-foreground">{f.label.toLowerCase()}</span>
              </React.Fragment>
            ))}
            . <Link href="/workspace/dashboard/settings/applicant" className="underline underline-offset-4">Profile</Link>
          </p>
          <Button type="button" variant="ghost" size="xs" className="shrink-0" onClick={() => setShowKnown(true)}>
            Edit
          </Button>
        </div>
      )}

      <div className={grid}>
        {openFields.filter((f) => plain.some((p) => p.key === f.key)).map(control)}
        {rowBlocks()}
      </div>

      <div className="mt-3 flex items-center gap-2">
        <Button type="submit" size="sm">
          {done ? "Save" : "Continue"}
        </Button>
        {input.repeat && rowN < input.repeat.max && (
          <Button type="button" variant="outline" size="sm" onClick={() => setRowN((k) => k + 1)}>
            <PlusIcon /> Add {input.repeat.label.toLowerCase()}
          </Button>
        )}
        {done && (
          <Button type="button" variant="ghost" size="sm" onClick={() => setEditing(false)}>
            Cancel
          </Button>
        )}
      </div>
    </form>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { displayValue, keyDef, normaliseKey } from "@/lib/forms/keys"
import { askedSections, formById, sectionLabel, type FormId } from "@/lib/forms/programs"
import { onProfileChange, sectionKeys, valuesFor } from "@/lib/forms/profile"
import { AskWidget } from "@/components/chat/ask-widget"
import type { ChatField, ReviewResult } from "@/lib/chat/form-tools"
import { Button } from "@/components/ui/button"

// Every answer, before anything is filled: grouped by the form's sections,
// each section reopening as the same controls it was asked with. "Looks
// right" is the confirmation; the values stay in the profile, and the model
// hears only that it was confirmed and how many answers there are.

export function ReviewWidget({ form, answered, compact, onSubmit }: { form: FormId; answered?: ReviewResult; compact?: boolean; onSubmit: (result: ReviewResult) => void }) {
  const program = formById(form)
  const [values, setValues] = React.useState(() => valuesFor(form))
  const [editing, setEditing] = React.useState<string | null>(null)
  const [done, setDone] = React.useState<ReviewResult | undefined>(answered)

  React.useEffect(() => onProfileChange(() => setValues(valuesFor(form))), [form])

  if (!program) return null
  const sections = askedSections(program)
  const filled = (key: string) => {
    const v = values[key]
    return v && v !== "skip" && v !== "unknown" ? v : ""
  }

  const confirm = () => {
    const answered = sections.reduce((n, s) => n + sectionKeys(s, values).filter((k) => filled(k)).length, 0)
    const result = { confirmed: true, sections: sections.length, answered }
    setDone(result)
    onSubmit(result)
  }

  return (
    <div data-slot="review-widget" className="rounded-lg border bg-muted/30 p-3 text-sm">
      <div className="mb-2 flex items-center justify-between gap-2">
        <span className="font-medium">{program.code}</span>
        {done && <span className="text-muted-foreground">Confirmed</span>}
      </div>
      <div className="flex flex-col divide-y">
        {sections.map((s) => {
          const keys = sectionKeys(s, values).filter((k) => filled(k))
          if (!keys.length && !s.keys.length) return null
          if (editing === s.n) {
            const fields: ChatField[] = s.keys.map((key) => {
              const def = keyDef(key)!
              return { key, label: def.label, kind: def.kind, options: def.options, multi: def.multi, tone: def.tone, href: def.href }
            })
            return (
              <div key={s.n} className="py-2">
                <AskWidget
                  input={{ section: s.n, title: sectionLabel(program, s.n), fields, repeat: s.repeat ? { ...s.repeat, min: 1 } : undefined }}
                  form={form}
                  compact={compact}
                  onSubmit={() => setEditing(null)}
                />
              </div>
            )
          }
          return (
            <div key={s.n} className="py-2">
              <div className="flex items-center justify-between gap-2">
                <span className="font-medium">{sectionLabel(program, s.n)}</span>
                {!done && (
                  <Button type="button" variant="ghost" size="xs" className="text-muted-foreground" onClick={() => setEditing(s.n)}>
                    Edit
                  </Button>
                )}
              </div>
              {keys.length ? (
                <dl className={cn("mt-1 grid gap-x-4 gap-y-0.5", compact ? "grid-cols-1" : "sm:grid-cols-2")}>
                  {keys.map((k) => (
                    <div key={k} className="flex min-w-0 justify-between gap-3 text-muted-foreground">
                      <dt className="truncate">{keyDef(k)?.label ?? k}</dt>
                      <dd className="truncate text-right text-foreground">{displayValue(normaliseKey(k), values[k])}</dd>
                    </div>
                  ))}
                </dl>
              ) : (
                <p className="mt-1 text-muted-foreground">Nothing answered.</p>
              )}
            </div>
          )
        })}
      </div>
      {!done && (
        <div className="mt-3">
          <Button type="button" size="sm" onClick={confirm} disabled={editing !== null}>
            Looks right
          </Button>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"

import { formById, type FormId } from "@/lib/forms/programs"
import { loadFormState, onProfileChange, progress, valuesFor } from "@/lib/forms/profile"

// Sections done of the form in hand, above the composer while a form is
// active. From livingston's FormProgress: the count is the record's, never
// the model's tally, so it cannot lag a section the widget already saved.

export function FormProgress({ form }: { form: FormId }) {
  const program = formById(form)
  const read = React.useCallback(() => (program ? progress(program, loadFormState(form), valuesFor(form)) : { done: 0, total: 0 }), [form, program])
  const [state, setState] = React.useState(read)
  React.useEffect(() => {
    setState(read())
    return onProfileChange(() => setState(read()))
  }, [read])
  if (!program || !state.total) return null
  const pct = Math.round((state.done / state.total) * 100)
  return (
    <div data-slot="form-progress" className="flex items-center gap-3 text-xs text-muted-foreground">
      <span className="shrink-0 font-medium text-foreground">{program.code}</span>
      <div className="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-muted">
        <div className="h-full rounded-full bg-primary transition-[width]" style={{ width: `${pct}%` }} />
      </div>
      <span className="shrink-0 tabular-nums">
        {state.done} of {state.total} sections
      </span>
    </div>
  )
}

import { atRow, isKnownKey, keyDef, normaliseKey, optionsFor, type CanonicalKey, type FieldKind } from "@/lib/forms/keys"
import { formById, isFormId, sectionOf, type FormId, type ProgramForm } from "@/lib/forms/programs"
// The shape of a run step this file reads — the kind and the tool's input.
// The agent runner's own Step is wider; this is what travels with the widgets.
type Step = { kind: string; input?: unknown }

// The contract between the Filer's client-side tools and the widgets that
// answer them. The model's `ask` input arrives here and is settled against
// the vocabulary — kinds, options and tones are the form's, whatever the
// model wrote — the way livingston's parseFieldBlock settled its prose block.

export type FieldTone = "caution" | "info"

export type ChatField = {
  key: CanonicalKey
  label: string
  kind: FieldKind
  hint?: string
  placeholder?: string
  /** `value|Label`. */
  options?: string[]
  multi?: boolean
  required?: boolean
  tone?: FieldTone
  href?: string
}

export type AskInput = {
  section: string
  title: string
  intro?: string
  fields: ChatField[]
  repeat?: { key: string; label: string; min: number; max: number }
}

export type AskResult =
  | { section: string; answered: CanonicalKey[]; skipped: CanonicalKey[]; next: { section: string; title: string; open: CanonicalKey[] } | null }
  | { error: string }
export type ReviewResult = { confirmed: boolean; sections: number; answered: number }
export type FillResult = { ok: boolean; filename?: string; pages?: number; bytes?: number; filled?: number; unmapped?: CanonicalKey[]; error?: string }
export type RememberResult = { kept: CanonicalKey[]; rejected: CanonicalKey[] }

const KINDS: FieldKind[] = ["text", "textarea", "number", "money", "date", "tel", "email", "ssn", "select", "radio", "checkbox", "yesno", "attest"]

/**
 * The model's fields, settled. A key the form does not ask is an error, not
 * a widget; a key with fixed values is asked with them whatever the model
 * wrote; an attestation is boxed and linked to its page.
 */
export function settleAsk(raw: unknown, form: ProgramForm | undefined): { input: AskInput } | { error: string } {
  const r = (raw ?? {}) as Record<string, unknown>
  const section = String(r.section ?? "").trim()
  const title = String(r.title ?? "").trim() || section
  const list = Array.isArray(r.fields) ? r.fields : []
  if (!list.length) return { error: "ask needs at least one field" }
  const unknown: string[] = []
  const fields: ChatField[] = []
  for (const item of list) {
    const f = (item ?? {}) as Record<string, unknown>
    const key = String(f.key ?? "").trim()
    if (!key) continue
    if (!isKnownKey(key) || (form && !sectionOf(form, key))) {
      unknown.push(key)
      continue
    }
    const def = keyDef(key)!
    let kind: FieldKind = KINDS.includes(f.kind as FieldKind) ? (f.kind as FieldKind) : def.kind
    let options = Array.isArray(f.options) ? f.options.filter((o): o is string => typeof o === "string") : undefined
    const fixed = optionsFor(key)
    if (fixed) {
      options = fixed.options
      kind = def.kind
    }
    if ((kind === "select" || kind === "radio" || kind === "checkbox") && !options?.length) kind = "text"
    fields.push({
      key,
      label: typeof f.label === "string" && f.label.trim() ? f.label.trim() : def.label,
      kind,
      options,
      multi: def.multi,
      hint: typeof f.hint === "string" ? f.hint : undefined,
      placeholder: typeof f.placeholder === "string" ? f.placeholder : undefined,
      required: f.required === true,
      tone: kind === "attest" ? "caution" : def.tone,
      href: def.href,
    })
  }
  if (unknown.length) return { error: `${form?.code ?? "The form"} does not ask ${unknown.join(", ")}. Use only keys from form_schema.` }
  if (!fields.length) return { error: "ask needs at least one field" }
  const rep = r.repeat && typeof r.repeat === "object" ? (r.repeat as Record<string, unknown>) : undefined
  const repeat =
    rep && typeof rep.key === "string"
      ? { key: rep.key, label: String(rep.label ?? "Row"), min: Math.max(1, Number(rep.min) || 1), max: Math.max(1, Number(rep.max) || 8) }
      : fields.some((f) => f.key.includes("[n]"))
        ? { key: fields.find((f) => f.key.includes("[n]"))!.key.split("[")[0], label: "Person", min: 1, max: 8 }
        : undefined
  return { input: { section, title, intro: typeof r.intro === "string" ? r.intro : undefined, fields, repeat } }
}

/** `household[n].dob` on row 3 → `household[3].dob`; other keys unchanged. */
export const keyOnRow = (key: string, n: number) => (key.includes("[n]") ? atRow(key, n) : key.replace(/\[\d+\]/, `[${n}]`))

export const rowKeys = (fields: ChatField[]) => fields.filter((f) => normaliseKey(f.key).includes("[n]"))
export const plainKeys = (fields: ChatField[]) => fields.filter((f) => !normaliseKey(f.key).includes("[n]"))

/** The form a run is about: the last form named in any tool input, else the remembered one. */
export function activeFormOf(steps: Step[], fallback: FormId | null): FormId | null {
  for (let i = steps.length - 1; i >= 0; i -= 1) {
    const step = steps[i]
    if (step.kind !== "tool" && step.kind !== "ask") continue
    const form = (step.input as { form?: unknown } | undefined)?.form
    if (isFormId(form)) return form
  }
  return fallback
}

export const formFor = (id: FormId | null) => (id ? formById(id) : undefined)

